/* ===== 纯函数区（第一个无属性 script）：可被 Node _test.js 提取并断言 ===== */
function sha1(bytes){
  var H=[0x67452301,0xEFCDAB89,0x98BADCFE,0x10325476,0xC3D2E1F0];
  var msg = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
  var l = msg.length;
  // pad so that (l + 1 + pad + 8) is a multiple of 64
  var k = (l + 1 + 8) % 64;
  var pad = k === 0 ? 0 : (64 - k);
  var total = l + 1 + pad + 8;
  var p = new Uint8Array(total);
  p.set(msg);
  p[l] = 0x80;
  var bitLen = l * 8;
  var hi = Math.floor(bitLen / 0x100000000);
  var lo = bitLen >>> 0;
  p[total-8]=(hi>>>24)&0xff; p[total-7]=(hi>>>16)&0xff; p[total-6]=(hi>>>8)&0xff; p[total-5]=hi&0xff;
  p[total-4]=(lo>>>24)&0xff; p[total-3]=(lo>>>16)&0xff; p[total-2]=(lo>>>8)&0xff; p[total-1]=lo&0xff;
  var w = new Array(80);
  for(var off=0; off<total; off+=64){
    for(var i=0;i<16;i++){
      var j=off+i*4;
      w[i]=(p[j]<<24)|(p[j+1]<<16)|(p[j+2]<<8)|p[j+3];
    }
    for(var i=16;i<80;i++){
      var n=w[i-3]^w[i-8]^w[i-14]^w[i-16];
      w[i]=(n<<1)|(n>>>31);
    }
    var a=H[0],b=H[1],c=H[2],d=H[3],e=H[4];
    for(var i=0;i<80;i++){
      var f,k;
      if(i<20){f=(b&c)|((~b)&d);k=0x5A827999;}
      else if(i<40){f=b^c^d;k=0x6ED9EBA1;}
      else if(i<60){f=(b&c)|(b&d)|(c&d);k=0x8F1BBCDC;}
      else{f=b^c^d;k=0xCA62C1D6;}
      var tmp=(((a<<5)|(a>>>27))+f+e+k+w[i])>>>0;
      e=d;d=c;c=(b<<30)|(b>>>2);b=a;a=tmp;
    }
    H[0]=(H[0]+a)>>>0;H[1]=(H[1]+b)>>>0;H[2]=(H[2]+c)>>>0;H[3]=(H[3]+d)>>>0;H[4]=(H[4]+e)>>>0;
  }
  var out=new Uint8Array(20);
  for(var i=0;i<5;i++){
    out[i*4]=(H[i]>>>24)&0xff;out[i*4+1]=(H[i]>>>16)&0xff;out[i*4+2]=(H[i]>>>8)&0xff;out[i*4+3]=H[i]&0xff;
  }
  return out;
}
function bytesToHex(b){
  var s='';
  for(var i=0;i<b.length;i++) s+=(b[i]>>>4).toString(16)+(b[i]&0xf).toString(16);
  return s;
}
function concatBytes(a,b){
  var o=new Uint8Array(a.length+b.length);
  o.set(a,0); o.set(b,a.length);
  return o;
}
function hmacSha1(keyBytes, msgBytes){
  var BS=64;
  var key=keyBytes;
  if(key.length>BS) key=sha1(key);
  if(key.length<BS){ var k2=new Uint8Array(BS); k2.set(key); key=k2; }
  var oKey=new Uint8Array(BS), iKey=new Uint8Array(BS);
  for(var i=0;i<BS;i++){ oKey[i]=key[i]^0x5c; iKey[i]=key[i]^0x36; }
  var inner=sha1(concatBytes(iKey,msgBytes));
  return sha1(concatBytes(oKey,inner));
}
var B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function base32Decode(s){
  s=String(s).toUpperCase().replace(/=+$/,'').replace(/\s+/g,'');
  var bits=0, value=0, out=[];
  for(var i=0;i<s.length;i++){
    var idx=B32.indexOf(s[i]);
    if(idx<0) continue;
    value=(value<<5)|idx; bits+=5;
    if(bits>=8){ bits-=8; out.push((value>>bits)&0xff); }
  }
  return Uint8Array.from(out);
}
function base32Encode(bytes){
  var out='', buffer=0, bits=0;
  for(var i=0;i<bytes.length;i++){
    buffer=(buffer<<8)|bytes[i]; bits+=8;
    while(bits>=5){ bits-=5; out+=B32[(buffer>>bits)&0x1f]; }
  }
  if(bits>0) out+=B32[(buffer<<(5-bits))&0x1f];
  return out;
}
function hotp(secret, counter, digits){
  digits=digits||6;
  var buf=new Uint8Array(8);
  var c=counter>>>0;
  buf[4]=(c>>>24)&0xff;buf[5]=(c>>>16)&0xff;buf[6]=(c>>>8)&0xff;buf[7]=c&0xff;
  var mac=hmacSha1(secret,buf);
  var off=mac[19]&0x0f;
  var bin=((mac[off]&0x7f)<<24)|((mac[off+1]&0xff)<<16)|((mac[off+2]&0xff)<<8)|(mac[off+3]&0xff);
  var code=(bin%Math.pow(10,digits)).toString();
  while(code.length<digits) code='0'+code;
