function totp(secret, timeMs, step, digits){
  step=step||30; digits=digits||6;
  var counter=Math.floor((timeMs/1000)/step);
  return hotp(secret, counter, digits);
}
function remaining(timeMs, step){
  step=step||30;
  var t=Math.floor(timeMs/1000);
  return step-(t%step);
}
function genSecret(byteLen){
  byteLen=byteLen||20;
  var b=new Uint8Array(byteLen);
  if(typeof crypto!=='undefined' && crypto.getRandomValues) crypto.getRandomValues(b);
