function validateSecret(s){
  if(!s) return false;
  s=String(s).toUpperCase().replace(/=+$/,'').replace(/\s+/g,'');
  if(s.length===0) return false;
  for(var i=0;i<s.length;i++) if(B32.indexOf(s[i])<0) return false;
  return true;
}
